  + 'import { AvatarImg } from "./avatar-img";\n'
  + 'import { buildAvatarStore } from "./avatar-store";\n'
  + '\n'
  + 'interface AvatarProps {\n'
  + '  size: string;\n'
  + '  color?: ColorName;\n'
  + '  children?: React.ReactNode;\n'
  + '}\n'
  + '\n'
  + 'type AvatarComponent = FC<AvatarProps> & {\n'
