  + '\n'
  + 'const Avatar: AvatarComponent = (props: AvatarProps) => {\n'
  + '  const avatarStore = buildAvatarStore();\n'
  + '\n'
  + '  return (\n'
  + '    <AvatarContext value={avatarStore}>\n'
  + '      <AvatarInternal {...props} />\n'
  + '    </AvatarContext>\n'
  + '  );\n'
  + '};\n'
  + '\n'
  + 'Avatar.displayName = "Avatar";\n'
  + '\n'
  + 'Avatar.Img = AvatarImg;\n'
  + 'Avatar.Fallback = AvatarFallback;\n'
  + '\n'
  + 'const AvatarInternal: FC<AvatarProps> = (props) => {\n'
  + '  const { size, color = "gray", children } = props;\n'
