  + '  const theme = useTheme();\n'
  + '  const jss = useJss();\n'
  + '\n'
  + '  const avatarStore = useAvatarStore();\n'
  + '  const imgState = useStore(avatarStore, (state) => state.imgState);\n'
  + '\n'
  + '  const stx = jss.hash({\n'
  + '    "--avatar-size": size,\n'
