  + '      .toHexString(),\n'
  + '  });\n'
  + '\n'
  + '  return (\n'
  + '    <span\n'
  + '      className={classNames(styles.avatar, stx)}\n'
  + '      data-avatar-img-loaded={imgState === "loaded" ? true : undefined}\n'
  + '    >\n'
  + '      {children}\n'
  + '    </span>\n'
  + '  );\n'
  + '};\n'
  + '\n'
  + 'export { Avatar };\n'
